import type { FastifySchema } from "fastify";
import { routeFeatures } from "../company-features.js";

// Documentation projections only. Source review does not establish handler
// verification and these schemas must never change runtime route.schema.
type Schema = Record<string, any>;
type Contract = FastifySchema & Record<string, unknown>;
const text: Schema = { type: "string" }, bool: Schema = { type: "boolean" };
const timestamp: Schema = { type: "string", format: "date-time" };
const positive: Schema = { type: "integer", minimum: 1, maximum: Number.MAX_SAFE_INTEGER };
const opening: Schema = { type: "integer", minimum: 0, maximum: Number.MAX_SAFE_INTEGER };
const nullable = (schema: Schema): Schema => ({ ...schema, nullable: true,
  ...(Array.isArray(schema.enum) && !schema.enum.includes(null) ? { enum: [...schema.enum, null] } : {}),
});
const object = (properties: Record<string, Schema>, required = Object.keys(properties), additionalProperties = false): Schema => ({ type: "object", properties, required, additionalProperties });
const array = (items: Schema): Schema => ({ type: "array", items });
const bounded = (maxLength: number): Schema => ({ type: "string", minLength: 1, maxLength, description: "Nonblank text is trimmed; NUL is rejected." });
const optionalText = (maxLength: number): Schema => ({ type: "string", nullable: true, maxLength, description: "Omitted, null or empty input becomes null; other text must be nonblank, trimmed and NUL-free." });
const role: Schema = { type: "string", enum: ["owner", "manager", "staff", "resident"] };
const status: Schema = { type: "string", enum: ["active", "disabled"] };
const opaque: Schema = { type: "string", minLength: 1, maxLength: 4096, pattern: "^[^\\u0000]+$", description: "Exact opaque account ID: maximum 4096 UTF-8 bytes, not characters; no NUL. Preserve punctuation/Unicode and URL-encode the complete path value. Never normalize or trim it." };
const identifier: Schema = { type: "string", pattern: "^[A-Za-z0-9][A-Za-z0-9_|:@.\\-]{0,199}$", minLength: 1, maxLength: 200 };
const submissionKey: Schema = { type: "string", format: "uuid", pattern: "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$", description: "UUIDv4 for this exact submitted operation. Keep the original key and values when recovering; changed details under the same key conflict." };
const success = object({ success: { type: "boolean", enum: [true] } });
const ignoredQuery: Schema = { type: "object", additionalProperties: true, description: "No query filters are consumed by this handler; extra query values do not change authority or scope." };
const userParams = object({ userId: opaque });
function headers(write: boolean, company = false, support = true): Schema {
  return object({
    ...(write ? { origin: { ...text, description: "Exact configured application origin." }, "x-csrf-token": { ...text, description: "Current session CSRF value from bootstrap. No real value belongs in documentation or persisted explorer configuration." } } : {}),
    ...(support ? { "x-impersonation-id": { ...text, description: "Exact current bootstrap support-view context; omit/send empty for own account. It is an acknowledgment, not an authorization grant." } } : {}),
    ...(company ? { "x-company-id": { ...text, description: "Optional assertion of the effective actor's current membership company, not a cross-company selector." } } : {}),
  }, write ? ["origin", "x-csrf-token"] : [], true);
}
function error(description: string): Schema {
  return { description, ...object({ error: text, code: text, requestId: text }) };
}
function responses(body: Schema, write = false, options: { missing?: boolean; conflict?: boolean; rate?: boolean; large?: boolean } = {}): Schema {
  return {
    200: { ...body, description: body.description ?? "Authorized operation completed with this response projection." },
    401: error("Current browser session is missing, invalid or expired."),
    403: error("Fresh authority, verification, company/source scope, support context, hosted edge validation or write Origin/CSRF rejects access."),
    ...(write ? { 400: error("Malformed JSON or the operation's documented fields/versions are invalid."), 413: error("Request exceeds the applicable body limit."), 415: error("Unsupported request content type.") } : {}),
    ...(options.missing ? { 404: error("Exact source account, membership, property, invitation or operation is unavailable within authorized scope.") } : {}),
    ...(options.conflict ? { 409: error("Current source/version/identity/submission or support context changed. Retain submitted values and review current state before another operation.") } : {}),
    ...(options.rate ? { 429: error("Provider/cooldown or configured request quota prevents another attempt. Honor Retry-After when supplied; do not repeatedly dispatch external actions.") } : {}),
    ...(options.large ? { 422: error("The complete supported selection exceeds the documented size bound; no partial complete-list claim is made.") } : {}),
    503: error("Provider/database or application processing could not be confirmed. A dispatched write can be uncertain; use its documented recovery instead of blind replay."),
  };
}
const ownReadSupport = "Authorized support views may read the effective target's projection under current session/context checks; target permissions still apply. Disabled/unavailable projections do not grant business access.";
const deniedWriteSupport = "Authenticated writes are denied while impersonating; return to the signed-in actor before submitting.";
const platformReadSupport = "Only an effective principal with platform.manage can read. Delegated Support cannot target platform accounts; an owner's authorized view of another platform owner still uses that target's actual permissions.";
function reviewed(key: string, file: string, line: number, summary: string, audience: string, scope: string, support: string, schema: Contract): Contract {
  const write = !key.startsWith("GET ");
  const invitationCompanyFence = ["GET /api/invitations/delivery", "GET /api/invitations", "POST /api/invitations", "POST /api/invitations/:invitationId/revoke", "POST /api/invitations/:invitationId/replace"].includes(key);
  return {
    operationId: key.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/_$/, ""),
    tags: [key.includes("/invitations") ? "Accounts and invitations" : "People and access"],
    summary, security: [{ sessionCookie: [] }], querystring: ignoredQuery,
    headers: headers(write, invitationCompanyFence || key.includes("/company/") || key.includes("/resident/")),
    ...schema,
    description: `${schema.description ?? ""}\n\nSource: ${file}:${line}; adjacent named helpers and serializers are part of this source review.`,
    "x-pf-contract-status": "source-reviewed", "x-pf-validation-status": "not-handler-verified",
    "x-pf-audience": audience, "x-pf-authentication": schema["x-pf-authentication"] ?? "Server-managed cookie session with fresh account/membership and support-context checks; authenticated mutations require exact Origin and X-CSRF-Token. Endpoint-specific verification/exit exceptions are stated below.",
    "x-pf-authorization": scope, "x-pf-support": support,
    "x-pf-features": routeFeatures(key.slice(key.indexOf(" ") + 1)),
    "x-pf-feature-policy": "Listed areas use the existing fresh company feature policy when the effective account has active membership: disabled blocks the area; read_only blocks non-GET/HEAD/OPTIONS writes. An empty list adds no feature gate. These feature labels never grant role, company or property authority.",
    "x-pf-sources": [`${file}:${line}`, "server/src/access.ts:permissions/companyScope", "server/src/sessions.ts:authenticate", "server/src/request-errors.ts:registerRequestErrors"],
  };
}
const definitions: Record<string, Contract> = {};
function add(key: string, file: string, line: number, summary: string, audience: string, scope: string, support: string, schema: Contract) {
  definitions[key] = reviewed(key, file, line, summary, audience, scope, support, schema);
}

const userSummary = object({ id: text, name: nullable(text), email: text, status: text, platformRole: nullable(text), emailVerified: bool });
const companySummary = object({ id: text, name: text, status: text });
