const featureModes = Object.fromEntries(["properties", "leasing", "maintenance", "documents", "finances", "reports", "inspections", "agreements", "notifications", "resident_portal"].map(key => [key, { type: "string", enum: ["enabled", "read_only", "disabled"] }]));
add("GET /api/bootstrap", "server/src/application.ts", 384, "Restore this session's effective account and workspace", "Any current browser session, including verification recovery and unavailable support projections", "No business permission is needed merely to restore session metadata. Returned permissions are derived from the effective account; unavailable support views force an empty permission list and /access destination.", "Bootstrap is exempt from X-Impersonation-ID acknowledgment and verification blocking so a stale/unavailable view can display its exit controls. It never grants the actor's platform authority to the target.", {
  headers: headers(false, false, false), description: "Returns only the selected user/membership fields, permissions, destination, CSRF value, support context and feature map. Treat csrfToken and contextId as private transient session state; never capture them in examples. Reads may refresh idle session expiry. Not a company/property authorization bypass.",
  response: responses(object({ user: userSummary, membership: bootstrapMembership, permissions: array(text), destination: text,
    csrfToken: { ...text, readOnly: true, description: "Private transient session CSRF value; no example/default is supplied." },
    impersonation: nullable(object({ actor: object({ id: text, name: nullable(text), email: text }), expiresAt: timestamp, contextId: text, readOnly: { type: "boolean", enum: [true] }, unavailable: bool })),
    companyFeatures: nullable(object(featureModes)),
  })),
});

const profileLimits: Record<string, number> = { preferredName: 200, phone: 40, alternatePhone: 40, addressLine1: 200, addressLine2: 200, city: 100, region: 100, postalCode: 30, country: 100, emergencyContactName: 200, emergencyContactPhone: 40, emergencyRelationship: 100 };
const profileFields = Object.fromEntries(Object.entries(profileLimits).map(([key, max]) => [key, optionalText(max)]));
profileFields.preferredContact = { type: "string", nullable: true, enum: ["email", "phone", null], description: "Phone preference requires primary phone; emergency phone/relationship requires emergency contact name." };
